"use client"

import Tag from "@/components/tags/Tag"

type Vend = {
  name: string
  year?: string
}

type Props = {
  businessName: string
  displayName: string
  profileImageUrl?: string
  merchTags: string[]
  previousVends: Vend[]
  locationText: string
  email: string
}

export default function ProfileSidebar({
  businessName,
  displayName,
  profileImageUrl,
  merchTags,
  previousVends,
  locationText,
  email,
}: Props) {
  return (
    <aside
      className="
        w-[316px] h-[982px]
        bg-white
        flex flex-col justify-between items-center
        px-[20px] py-[40px]
        gap-[10px]
        relative
      "
    >
      {/* Main content */}
      <div className="w-[276px] flex flex-col items-center gap-[30px]">
        {/* Image & names */}
        <div className="w-full flex flex-col items-center gap-[12px]">
          <div className="w-[189px] h-[189px] rounded-[15px] overflow-hidden bg-[#A5A5A5]/10">
            {profileImageUrl ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={profileImageUrl}
                alt="Profile"
                className="w-full h-full object-cover"
              />
            ) : null}
          </div>

          <p className="m-0 text-center font-inter font-normal text-[22px] leading-[27px] text-[#262626]">
            {businessName}
          </p>

          <p className="m-0 text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            {displayName}
          </p>
        </div>

        {/* Social icons placeholder */}
        <div className="flex items-center justify-center gap-[10px] h-[24px]">
          <div className="w-[24px] h-[24px] border border-[#262626]/30 rounded-full" />
          <div className="w-[24px] h-[24px] border border-[#262626]/30 rounded-full" />
          <div className="w-[24px] h-[24px] border border-[#262626]/30 rounded-full" />
        </div>

        {/* Merch tags */}
        <div className="w-full flex flex-wrap justify-center gap-[10px]">
          {merchTags.length === 0 ? (
            <Tag label="—" />
          ) : (
            merchTags.map((tag) => (
              <Tag key={tag} label={tag} />
            ))
          )}
        </div>

        {/* Previous vends */}
        <div className="w-full flex flex-col items-center gap-[12px]">
          <p className="m-0 text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            Previous Vends
          </p>

          {previousVends.length === 0 ? (
            <p className="m-0 text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              —
            </p>
          ) : (
            previousVends.map((vend, i) => (
              <p
                key={`${vend.name}-${i}`}
                className="m-0 text-center font-inter font-normal text-[15px] leading-[140%] text-[#262626]"
              >
                {vend.name}
                {vend.year && (
                  <span
                    className="
                      ml-[6px]
                      font-inter italic font-normal
                      text-[12px] leading-[140%]
                      text-[#A5A5A5]
                    "
                  >
                    {vend.year}
                  </span>
                )}
              </p>
            ))
          )}
        </div>

        {/* Location & email */}
        <div className="w-full flex flex-col items-center gap-[12px]">
          <div className="flex items-center gap-[5px]">
            <div className="w-[12px] h-[12px] bg-[#A5A5A5] rounded-[2px]" />
            <p className="m-0 font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              {locationText}
            </p>
          </div>

          <p className="m-0 font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5] text-center">
            {email}
          </p>
        </div>
      </div>

      {/* Watermark logo */}
      <div className="absolute top-[30px] left-1/2 -translate-x-1/2 opacity-50 pointer-events-none">
        <p className="m-0 font-inknut font-semibold text-[18.12px] tracking-[-0.02em] text-[#262626]">
          konfolio
        </p>
      </div>
    </aside>
  )
}
